UNITS = [
 {"id": "PEDS-U368", "ch": 47, "n": 1, "title": "Leukemia — Introduction & Types", "sec": "Leukemia, features and types · p215", "guide": "Leukemia is the m/c hematological malignancy. Its hallmarks are clonal proliferation plus arrest of maturation (the tumour cells are of immature cell series). Acute leukemia (ALL, AML) is far more common than chronic leukemia in children.", "qs": ["PEDS-C47-001", "PEDS-C47-002", "PEDS-C47-003", "PEDS-C47-004", "PEDS-C47-005", "PEDS-C47-006", "PEDS-C47-007", "PEDS-C47-008", "PEDS-C47-009", "PEDS-C47-010"]},
 {"id": "PEDS-U369", "ch": 47, "n": 2, "title": "ALL — Incidence & Predisposing Conditions", "sec": "ALL incidence and risk factors · p215", "guide": "ALL is the m/c malignancy in children, peak age 2–5 years, males > females. Increased-risk conditions: ataxia telangiectasia, Bloom's syndrome, SCID, Down syndrome, Fanconi's anemia, Le Fraumeni syndrome and environmental factors such as ionizing radiation.", "qs": ["PEDS-C47-011", "PEDS-C47-012", "PEDS-C47-013", "PEDS-C47-014", "PEDS-C47-015", "PEDS-C47-016", "PEDS-C47-017", "PEDS-C47-018", "PEDS-C47-019", "PEDS-C47-020", "PEDS-C47-021", "PEDS-C47-022"]},
 {"id": "PEDS-U370", "ch": 47, "n": 3, "title": "ALL — Immunophenotypic Classification", "sec": "ALL immunophenotypic classification · p215", "guide": "Based on cell type (CD markers by flow cytometry): pre-B cell — m/c: 85% — CD10 (marker of good prognosis), CD19, CD20, CD45 → good prognosis with treatment; mature B cell (and most common) — CD19, CD20, CD21 with surface Ig positivity → intensified treatment required; T cell — CD2, CD3, CD4, CD5, CD7, CD8 → mediastinal involvement plus CNS manifestations. The cytogenetic classification uses chromosome number and translocations.", "qs": ["PEDS-C47-023", "PEDS-C47-024", "PEDS-C47-025", "PEDS-C47-026", "PEDS-C47-027", "PEDS-C47-028", "PEDS-C47-029", "PEDS-C47-030", "PEDS-C47-031", "PEDS-C47-032", "PEDS-C47-033", "PEDS-C47-034", "PEDS-C47-035"]},
 {"id": "PEDS-U371", "ch": 47, "n": 4, "title": "ALL — General Features", "sec": "ALL general features · p216", "guide": "Bone marrow failure → pancytopenia (anemia, thrombocytopenia — seen as petechiae — and leukopenia; a few patients may still show leukocytes) with night bone pains from infiltration. Extramedullary involvement in > 60%: hepatosplenomegaly/splenomegaly, superficial lymphadenopathy (non-tender, firm, fixed, confluent), mediastinal involvement (tracheal compression, SVC syndrome with facial flushing/edema and jugular vein distension), CNS leukemia (cranial neuropathies, seizures, ↑ICT features) and painless testicular swelling.", "qs": ["PEDS-C47-036", "PEDS-C47-037", "PEDS-C47-038", "PEDS-C47-039", "PEDS-C47-040", "PEDS-C47-041", "PEDS-C47-042", "PEDS-C47-043", "PEDS-C47-044", "PEDS-C47-045", "PEDS-C47-046", "PEDS-C47-047", "PEDS-C47-048", "PEDS-C47-049", "PEDS-C47-050", "PEDS-C47-051"]},
 {"id": "PEDS-U372", "ch": 47, "n": 5, "title": "ALL — Diagnosis & Prognostic Classification", "sec": "ALL diagnosis and prognosis · p216", "guide": "Bone marrow aspiration and biopsy; aspiration may be normal. ≥ 25% lymphoblasts confirms ALL. Standard-risk/good prognosis: age 2–10 y, female, no CNS involvement, initial WBC < 50,000/mm³, pre-B cell subtype, hyperdiploidy (> 50 chromosomes) or trisomy 4, 10. High-risk/poor prognosis: age ≤ 1 y or > 10 y, male, CNS involvement, WBC > 50,000/mm³, B or T cell subtype, hypodiploidy (< 44 chromosomes), t(9;22) Philadelphia chromosome or t(4;11) infantile leukemia (< 1 y old).", "qs": ["PEDS-C47-052", "PEDS-C47-053", "PEDS-C47-054", "PEDS-C47-055", "PEDS-C47-056", "PEDS-C47-057", "PEDS-C47-058", "PEDS-C47-059", "PEDS-C47-060", "PEDS-C47-061", "PEDS-C47-062", "PEDS-C47-063", "PEDS-C47-064", "PEDS-C47-065", "PEDS-C47-066", "PEDS-C47-067", "PEDS-C47-068", "PEDS-C47-069", "PEDS-C47-070"]},
 {"id": "PEDS-U373", "ch": 47, "n": 6, "title": "ALL — Four Phases of Treatment", "sec": "ALL treatment phases · p217", "guide": "Phase I induction (prednisolone, L-asparaginase, anthracycline, vincristine) — induce remission and look for response: ↓ WBC count, no blasts in marrow and circulation = good response/good prognosis; minimal residual disease (MRD) is beyond conventional detection and is tested by flow cytometry/PCR. Phase II prophylactic CNS therapy — intrathecal methotrexate for subclinical CNS involvement. Phase III consolidation/intensification — methotrexate, epipodophyllotoxin, cyclophosphamide, cytosine-arabinoside — to tackle drug resistance and sustain remission. Phase IV maintenance (once a week for a year) — 6-mercaptopurine and methotrexate — to prevent relapse.", "qs": ["PEDS-C47-071", "PEDS-C47-072", "PEDS-C47-073", "PEDS-C47-074", "PEDS-C47-075", "PEDS-C47-076", "PEDS-C47-077", "PEDS-C47-078", "PEDS-C47-079", "PEDS-C47-080", "PEDS-C47-081", "PEDS-C47-082", "PEDS-C47-083", "PEDS-C47-084", "PEDS-C47-085", "PEDS-C47-086", "PEDS-C47-087", "PEDS-C47-088", "PEDS-C47-089", "PEDS-C47-090", "PEDS-C47-091"]},
 {"id": "PEDS-U374", "ch": 47, "n": 7, "title": "AML — FAB & WHO Classification", "sec": "AML classification · p217", "guide": "AML is the 2nd m/c type of leukemia. FAB: M0 minimal differentiation, M1 without maturation, M2 with maturation, M3 APML, M4 myelomonocytic leukemia, M5 monocytic leukemia, M6 erythroleukemia, M7 megakaryoblast leukemia. WHO/favourable: inversion 16, t(8;21), CEBPA gene mutation (transcription factor for myeloid maturation), NPM1 gene mutation; high risk: monosomy 5/7 and 5q deletion. Favourable genetics are treated with chemotherapy; high-risk disease needs hematopoietic stem cell transplantation (HSCT).", "qs": ["PEDS-C47-092", "PEDS-C47-093", "PEDS-C47-094", "PEDS-C47-095", "PEDS-C47-096", "PEDS-C47-097", "PEDS-C47-098", "PEDS-C47-099", "PEDS-C47-100", "PEDS-C47-101", "PEDS-C47-102", "PEDS-C47-103", "PEDS-C47-104", "PEDS-C47-105", "PEDS-C47-106", "PEDS-C47-107", "PEDS-C47-108", "PEDS-C47-109", "PEDS-C47-110"]},
 {"id": "PEDS-U375", "ch": 47, "n": 8, "title": "AML — Clinical Features & Treatment", "sec": "AML clinical features and treatment · p217", "guide": "Features resemble ALL, except that hepatosplenomegaly is rarely seen (present in M4, M5) and there is no lymphadenopathy. Very high WBC count → leukostasis → lung infiltrates and stroke manifestations; DIC in M3; gum hypertrophy (M4); chloroma/myeloid sarcoma = deposition of leukemia cells in skin due to extramedullary hematopoiesis. Diagnosis: marrow aspiration > 20% myeloblasts. Induction — cytosine arabinoside + daunorubicin; consolidation — cytosine arabinoside + etoposide; M3 (APML) — ATRA/tretinoin drives differentiation of the malignant cell into a mature cell.", "qs": ["PEDS-C47-111", "PEDS-C47-112", "PEDS-C47-113", "PEDS-C47-114", "PEDS-C47-115", "PEDS-C47-116", "PEDS-C47-117", "PEDS-C47-118", "PEDS-C47-119", "PEDS-C47-120", "PEDS-C47-121", "PEDS-C47-122", "PEDS-C47-123", "PEDS-C47-124", "PEDS-C47-125", "PEDS-C47-126", "PEDS-C47-127"]},
 {"id": "PEDS-U376", "ch": 47, "n": 9, "title": "Lymphoma — Types & Hodgkin Epidemiology", "sec": "Lymphoma types and Hodgkin epidemiology · p217", "guide": "Reed-Sternberg (RS) cell present (40%) = Hodgkin lymphoma/disease; RS cell absent (60%) = non-Hodgkin lymphoma. Hodgkin lymphoma affects 15–19-year-olds with male predominance; risk factors are infections (HHV6, CMV, EBV — EBV raises risk 4×) and autoimmune disorders such as SLE.", "qs": ["PEDS-C47-128", "PEDS-C47-129", "PEDS-C47-130", "PEDS-C47-131", "PEDS-C47-132", "PEDS-C47-133", "PEDS-C47-134", "PEDS-C47-135", "PEDS-C47-136", "PEDS-C47-137", "PEDS-C47-138"]},
 {"id": "PEDS-U377", "ch": 47, "n": 10, "title": "Hodgkin Lymphoma — Features, Grades & Types", "sec": "Hodgkin clinical features and types · p218", "guide": "Lymphadenopathy (m/c cervical) that is painless, matted, with firm rubbery consistency. Constitutional symptoms — high-grade fever (> 38°C), drenching night sweats, weight loss > 10% in 6 months — if absent = grade A (good prognosis), if present = grade B (poor prognosis). Classical HD: CD15/CD30 positive, RS cell (malignant transformation of a germinal B cell) with owl-eye inclusion body; nodular lymphocyte-predominant: CD20/CD45 with popcorn cells. Classical subtypes: nodular sclerosis (m/c worldwide, F > M, lacunar variant, EBV −, excellent), mixed cellularity (m/c in India, M > F, EBV +, good), lymphocyte rich (mononuclear, EBV +, excellent) and lymphocyte depleted (reticular, EBV +, poor).", "qs": ["PEDS-C47-139", "PEDS-C47-140", "PEDS-C47-141", "PEDS-C47-142", "PEDS-C47-143", "PEDS-C47-144", "PEDS-C47-145", "PEDS-C47-146", "PEDS-C47-147", "PEDS-C47-148", "PEDS-C47-149", "PEDS-C47-150", "PEDS-C47-151", "PEDS-C47-152", "PEDS-C47-153", "PEDS-C47-154", "PEDS-C47-155", "PEDS-C47-156", "PEDS-C47-157", "PEDS-C47-158", "PEDS-C47-159", "PEDS-C47-160", "PEDS-C47-161"]},
 {"id": "PEDS-U378", "ch": 47, "n": 11, "title": "Hodgkin Lymphoma — Ann Arbor Staging & Treatment", "sec": "Hodgkin staging and treatment · p218–219", "guide": "Modified Ann Arbor staging: I single lymph node; II ≥ 2 lymph nodes on one side of the diaphragm; III multiple lymph nodes above and below the diaphragm; IV multiple nodes plus organs affected. Stage annotations: X = bulky > 10 cm, E = extension into an extralymphatic site. Stages I–IIIB are favourable — ABVD chemotherapy (adriamycin, bleomycin, vinblastine, dacarbazine); unfavourable disease (stage IV, or any stage with X or E) — chemotherapy plus radiotherapy, including involved field radiation therapy (IFRT).", "qs": ["PEDS-C47-162", "PEDS-C47-163", "PEDS-C47-164", "PEDS-C47-165", "PEDS-C47-166", "PEDS-C47-167", "PEDS-C47-168", "PEDS-C47-169", "PEDS-C47-170", "PEDS-C47-171", "PEDS-C47-172", "PEDS-C47-173", "PEDS-C47-174", "PEDS-C47-175", "PEDS-C47-176", "PEDS-C47-177"]},
 {"id": "PEDS-U379", "ch": 47, "n": 12, "title": "Non-Hodgkin Lymphoma — Types & Clinical Features", "sec": "NHL types and features · p219", "guide": "NHL occurs at 5–15 years and is typed by lymphocyte of origin: B cell (Burkitt's lymphoma — m/c worldwide; diffuse large B cell lymphoma), T cell (lymphoblastic lymphoma — m/c in India; anaplastic large cell lymphoma) and intermediate cell. Endemic Burkitt (endemic to Africa, m/c worldwide) presents with jaw lesions (lytic bone lesions, draining sinuses, diffuse swelling) and generalized abdominal distension; sporadic Burkitt (m/c in India) presents with intra-abdominal tumours — mass per abdomen, unexplained abdominal pain, intussusception with tumour as lead point. EBV association is positive in endemic and ↓↓ in sporadic. T cell type resembles ALL and presents as a mediastinal mass.", "qs": ["PEDS-C47-178", "PEDS-C47-179", "PEDS-C47-180", "PEDS-C47-181", "PEDS-C47-182", "PEDS-C47-183", "PEDS-C47-184", "PEDS-C47-185", "PEDS-C47-186", "PEDS-C47-187", "PEDS-C47-188", "PEDS-C47-189", "PEDS-C47-190", "PEDS-C47-191", "PEDS-C47-192", "PEDS-C47-193", "PEDS-C47-194", "PEDS-C47-195"]},
 {"id": "PEDS-U380", "ch": 47, "n": 13, "title": "NHL — St. Jude Staging & Treatment", "sec": "NHL St. Jude staging and treatment · p220", "guide": "St. Jude staging: low risk — stage 1 (single lymph node, no other lesion) and stage 2 (multiple lymph nodes with a single resectable GI lesion); high risk — stage 3 (multiple nodes with non-resectable GI lesions) and stage 4 (non-resectable GI lesions with bone marrow/CNS involvement). Chemotherapy: cyclophosphamide, vincristine, prednisolone and doxorubicin for low risk; methotrexate is added for high risk.", "qs": ["PEDS-C47-196", "PEDS-C47-197", "PEDS-C47-198", "PEDS-C47-199", "PEDS-C47-200", "PEDS-C47-201", "PEDS-C47-202", "PEDS-C47-203", "PEDS-C47-204", "PEDS-C47-205"]},
 {"id": "PEDS-U381", "ch": 47, "n": 14, "title": "Langerhans Cell Histiocytosis — Features & Spectrum", "sec": "LCH features and spectrum · p220–221", "guide": "LCH (histiocytosis X) is a clonal proliferation of Langerhans-like cells with a wide, potentially multisystemic spectrum. Sites: bone (m/c; skull > jaw, missing/loose teeth), skin (scales with discharge, mimics seborrheic dermatitis and does not respond to its treatment — cradle cap), pituitary infiltration destroying the stalk → block in release of vasopressin/ADH from posterior pituitary granules → diabetes insipidus (MRI: loss of the posterior pituitary bright spot), lymphadenopathy and hepatosplenomegaly. Spectrum with increasing severity: eosinophilic granuloma (older children, lytic bone in skull) → Hand-Schüller-Christian disease (2–6 years; skull defect, DI, exophthalmos) → Letterer-Siwe disease (severe form, < 2 years; seborrheic dermatitis, ear discharge, hepatosplenomegaly with abnormal LFT, lymphadenopathy).", "qs": ["PEDS-C47-206", "PEDS-C47-207", "PEDS-C47-208", "PEDS-C47-209", "PEDS-C47-210", "PEDS-C47-211", "PEDS-C47-212", "PEDS-C47-213", "PEDS-C47-214", "PEDS-C47-215", "PEDS-C47-216", "PEDS-C47-217", "PEDS-C47-218", "PEDS-C47-219", "PEDS-C47-220", "PEDS-C47-221", "PEDS-C47-222", "PEDS-C47-223", "PEDS-C47-224", "PEDS-C47-225", "PEDS-C47-226", "PEDS-C47-227"]},
 {"id": "PEDS-U382", "ch": 47, "n": 15, "title": "LCH — Diagnosis & Treatment", "sec": "LCH diagnosis and treatment · p221", "guide": "Diagnosis on biopsy: immunohistochemistry for CD1a and CD207 (langerin); electron microscopy shows Birbeck granules with a tennis racket appearance. Treatment: simple lesion — curettage and intralesional steroids; multiple lesions — vinblastine (m/c), 6-mercaptopurine and prednisolone; refractory disease — cladribine.", "qs": ["PEDS-C47-228", "PEDS-C47-229", "PEDS-C47-230", "PEDS-C47-231", "PEDS-C47-232", "PEDS-C47-233", "PEDS-C47-234", "PEDS-C47-235", "PEDS-C47-236", "PEDS-C47-237", "PEDS-C47-238", "PEDS-C47-239", "PEDS-C47-240", "PEDS-C47-241"]},
]

