 {"sec": "AML classification · p217", "page": 217, "q": "In AML, favourable genetics are treated with chemotherapy while high-risk disease requires —", "opts": ["ATRA", "Splenectomy", "Stem cell transplantation", "Radiotherapy alone"], "ans": 2, "exp": "Response to therapy row: favourable → chemotherapy; high risk → hematopoietic stem cell transplantation (HSCT). (Book p217)", "type": "mcq", "id": "PEDS-C47-106"},
 {"sec": "AML classification · p217", "page": 217, "q": "True or False — In AML, high-risk genetics such as monosomy 7 are an indication for hematopoietic stem cell transplantation.", "opts": ["True", "False"], "ans": 0, "exp": "True — the high-risk group is managed with HSCT per the WHO classification table. (Book p217)", "type": "tf", "id": "PEDS-C47-107"},
 {"sec": "AML classification · p217", "page": 217, "q": "Odd one out (favourable risk factors in AML):", "opts": ["Monosomy 7", "Inversion 16", "NPM1 gene mutation", "t(8;21)"], "ans": 0, "exp": "Monosomy 7 is a high-risk factor; the others are favourable. (Book p217)", "type": "odd", "id": "PEDS-C47-108"},
