 {"sec": "NHL St. Jude staging and treatment · p220", "page": 220, "q": "A 9-year-old with Burkitt lymphoma has an unresectable abdominal mass with marrow involvement and CNS disease.", "opts": ["St. Jude stage 2 — low risk", "St. Jude stage 3 — low risk", "No staging needed", "St. Jude stage 4 — high risk"], "ans": 3, "exp": "Non-resectable GI lesions + marrow/CNS involvement = stage 4 (high risk, methotrexate added). (Book p220)", "type": "case", "stem": "A 9-year-old with Burkitt lymphoma has a non-resectable abdominal mass; marrow aspirate and CSF cytology both show lymphoma cells.", "id": "PEDS-C47-203"},
 {"sec": "NHL St. Jude staging and treatment · p220", "page": 220, "q": "True or False — St. Jude stages 3 and 4 of NHL are grouped as high risk.", "opts": ["True", "False"], "ans": 0, "exp": "True — low risk = stages 1–2; high risk = stages 3–4. (Book p220)", "type": "tf", "id": "PEDS-C47-204"},
 {"sec": "NHL St. Jude staging and treatment · p220", "page": 220, "q": "Odd one out (drugs of the low-risk NHL chemotherapy regimen):", "opts": ["Doxorubicin", "Methotrexate", "Cyclophosphamide", "Vincristine"], "ans": 1, "exp": "Methotrexate is used only if high risk; the low-risk regimen is cyclophosphamide, vincristine, prednisolone and doxorubicin. (Book p220)", "type": "odd", "id": "PEDS-C47-205"},
 {"sec": "LCH features and spectrum · p220–221", "page": 220, "q": "Langerhans cell histiocytosis is also known as ___.", "opts": ["Reticuloendotheliosis", "Myeloid sarcoma", "Histiocytosis X", "Letterer-Christian syndrome"], "ans": 2, "exp": "LCH is AKA histiocytosis X. (Book p220)", "type": "fill", "id": "PEDS-C47-206"},
